class InvoiceService {
  createInvoice(order: Order) {
    const invoice = new Invoice();
    // support multiple tax rules, coupons, loyalty points, giftcards
    applyTax(invoice, order);
    applyCoupons(invoice, order);
    applyLoyalty(invoice, order);
    applyGiftCard(invoice, order);
    // TODO: handle international VAT and future promotions
    save(invoice);
  }
}

// Version A
class BillingV1 {
  process(order: Order) {
    const invoice = computeBase(order);
    if (order.couponCode) invoice.apply(discountFor(order.couponCode));
    save(invoice);
  }
  // Add real extension hooks when customers request tangible variations
}

// Version B
interface DiscountProvider { apply(invoice: Invoice): void }
abstract class BillingV2 {
  protected providers: DiscountProvider[] = [];
  process(order: Order) {
    const invoice = computeBase(order);
    this.providers.forEach(p => p.apply(invoice));
    save(invoice);
  }
  // scaffolding for many future plugin implementations
}
